// spec: specs/writing-submit.md (1.1–1.4) · кейсы WSB-01, WSB-02, WSB-07, WSB-06 · запасной путь (подсчёт запросов, фокус, окна parent-3 / parent-b)
// seed: tests/seed.parent.spec.ts
// Общий ребёнок QA-AUTO-… (письмо 3, ~9 лет) на весь файл → serial. Окно ребёнка (сессия parent) живёт через все тесты;
// окно родителя — parent-3, окно чужой семьи — parent-b (одну сессию в двух открытых окнах не держим).
// Не прогонять при записи — запуск только по /qa-regress.
import { BrowserContext, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  birthYearForAge,
  createChildWithLevels,
  drawStrokes,
  expectFocusInside,
  handoverToChildHome,
  openSharedUserPage,
  openWritingCatalog,
  openWritingTask,
  qaChildName,
  qaWritingText,
  trackSubmits,
  typeDraft,
  vis,
  writingSurface,
} from './writing.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

test.describe('Отправка письма — подтверждение, одна отправка, рукопись, чужая работа (autotest-writer)', () => {
  const childName = qaChildName();
  let childId = '';
  let kid: { context: BrowserContext; page: Page };
  let submits: ReturnType<typeof trackSubmits>;
  // Из 1.2 для 1.3: адрес отзыва и уникальный текст отправленной работы.
  let feedbackUrl = '';
  let sentText = '';

  test.beforeAll(async ({ browser }, testInfo) => {
    test.setTimeout(2 * 60_000);
    kid = await openSharedUserPage(browser, testInfo, 'parent');
    childId = await createChildWithLevels(kid.page, childName, { birthYear: birthYearForAge(9), writingLevel: 3 });
    await handoverToChildHome(kid.page, childId, childName);
    submits = trackSubmits(kid.page);
  });

  test.afterAll(async () => {
    await kid?.context.close();
  });

  test('Окно подтверждения «לשלוח לבנג׳י?»: фокус внутри, Esc и «עוד לא» — без отправки, текст цел @desktop @data #b39e08', async ({}, testInfo) => {
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    await openWritingCatalog(page, childId);
    await openWritingTask(page);
    const text = qaWritingText();
    await typeDraft(page, text);
    submits.reset();

    // «לסיים תרגול» → своё окно приложения (S-13; реджект rej_3292… п.4)
    await s.finish.click();
    await expect(s.confirm).toBeVisible();
    await expect(s.send).toBeVisible();
    await expect(s.notYet).toBeVisible();
    for (let i = 0; i < 3; i++) {
      await page.keyboard.press('Tab');
      await expectFocusInside(s.confirm, `Tab ${i + 1} в окне подтверждения`);
    }

    // Esc = «нет»: окно закрыто, ничего не отправлено, текст на месте (AC1 «עיבוד מתחיל רק לאחר אישור שליחה מפורש»)
    await page.keyboard.press('Escape');
    await expect(s.confirm).toBeHidden();
    await expect(s.typingField).toHaveValue(text);

    // «עוד לא» — то же
    await s.finish.click();
    await expect(s.confirm).toBeVisible();
    await s.notYet.click();
    await expect(s.confirm).toBeHidden();
    await expect(s.typingField).toHaveValue(text);
    expect(submits.count(), 'submit_writing_attempt вызван без подтверждения').toBe(0);
  });

  test('Двойной клик «לשלוח» — одна отправка; «בנג׳י קורא…» держит фокус; затем отзыв @desktop @data #b39e08', async ({}, testInfo) => {
    test.setTimeout(2 * 60_000);
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    // Черновик из 1.1 на месте; если тест 1.1 не дошёл — новый
    if (!(await s.typingField.isVisible())) {
      await openWritingCatalog(page, childId);
      await openWritingTask(page);
      await typeDraft(page, qaWritingText());
    }
    sentText = await s.typingField.inputValue();
    submits.reset();

    await s.finish.click();
    await expect(s.confirm).toBeVisible();
    await s.send.dblclick();

    // Окно обработки: фокус не выходит наружу (S-13 G; реджект п.3)
    await expect(s.processing).toBeVisible();
    for (let i = 0; i < 3; i++) {
      await page.keyboard.press('Tab');
      await expectFocusInside(s.processing, `Tab ${i + 1} в окне обработки`);
    }
    await page.keyboard.press('Shift+Tab');
    await expectFocusInside(s.processing, 'Shift+Tab в окне обработки');

    // Отзыв (D6)
    await expect(s.feedbackNext).toBeVisible({ timeout: 60_000 });
    // AC2 «שליחה חוזרת עם אותו מזהה אינה יוצרת שתי תוצאות»: все запросы — с одним id отправки
    expect(submits.count(), 'submit_writing_attempt не вызывался').toBeGreaterThanOrEqual(1);
    expect(submits.keys(), `разные id отправки: ${submits.keys().join(', ')}`).toHaveLength(1);
    feedbackUrl = page.url();
  });

  test('Чужая семья (parent-b) по прямому адресу отзыва не видит работу @desktop @data #b39e08', async ({ asUser }) => {
    expect(feedbackUrl, 'нет адреса отзыва из теста 1.2').not.toBe('');
    const other = await asUser('parent-b');
    await other.goto(feedbackUrl);
    // Дождаться, что экран отрисован: «לא מצאתי…» или любой заголовок экрана, куда перевели
    await expect(vis(other.getByText(/לא מצאתי/).or(other.getByRole('heading')))).toBeVisible();
    // S-13 G «אין חשיפת נתונים של ילד אחר»: текста отправленной работы нет
    const tag = sentText.split(' ')[0];
    await expect(other.getByText(tag)).toHaveCount(0);
  });

  test('Рукопись: 3 штриха → отзыв «…לא הצליח לקרוא את כתב היד… זה לא בגללך» без балла; у родителя «הכתב טרם נקרא» @desktop @data #b39e08', async ({ asUser }, testInfo) => {
    test.setTimeout(2 * 60_000);
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    await openWritingCatalog(page, childId);
    await openWritingTask(page);
    if ((await s.handMode.getAttribute('aria-checked')) !== 'true') await s.handMode.click();
    await drawStrokes(page, 3);
    await expect(s.saved).toBeVisible({ timeout: 30_000 });

    await s.finish.click();
    await expect(s.confirm).toBeVisible();
    await s.send.click();

    // AC5 «כתב לא מזוהה אינו מוצג ככישלון של הילד»; AC4 fallback
    await expect(vis(page.getByText(/לא הצליח לקרוא את כתב היד/))).toBeVisible({ timeout: 60_000 });
    await expect(vis(page.getByText(/זה לא בגללך/))).toBeVisible();
    await expect(vis(page.getByText(/ציון|\d+\s*\/\s*\d+|\d+%/))).toBeHidden();

    // Родитель (окно parent-3): наблюдения → письмо → «הכתב טרם נקרא» (AC4 «שומר את ההגשה כממתינה»)
    const parent = await asUser('parent-3');
    await parent.goto(`/children/${childId}/observations`);
    await vis(parent.getByRole('tab', { name: /כתיבה/ }).or(parent.getByRole('button', { name: /^כתיבה$/ }))).click(); // TODO verify selector (вкладка «כתיבה»)
    await expect(vis(parent.getByText(/הכתב טרם נקרא/))).toBeVisible();
  });
});
